import React from "react";
import { useNavigate } from "react-router-dom";
import { Carousel } from "react-responsive-carousel";
import "react-responsive-carousel/lib/styles/carousel.min.css";

function Sketches() {
  const navigate = useNavigate();

  const images2 = [
    "/bodyfacec1.avif",
    "/bodyfacec2.avif",
    "/bodyfacec3.avif",
    "/bodyfacec4.avif",
    "/bodyfacec5.avif",
    "/bodyfacec6.avif",
  ];

  const images = [
    "sketch1.avif",
    "sketch2.avif",
    "sketch3.avif",
    "sketch4.avif",
    "sketch5.avif",
    "sketch6.avif",
    "sketch7.avif",
    "sketch8.avif",
  ];

  return (
    <>
      {/* Go Back Button */}
      <p
        className="underline text-base sm:text-lg md:text-xl lg:text-2xl cursor-pointer pl-5 mt-5"
        onClick={() => navigate(-1)}
      >
        Go Back
      </p>

      {/* Heading Section */}
      <div className="flex flex-col items-center justify-center mt-10">
        <h2 className="text-5xl font-bold text-red-500 text-center mt-2 mb-10">
          SKETCHES AND PAINTINGS
        </h2>
      </div>

      {/* Image Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-10 px-4 md:px-10 lg:px-20">
        {images.map((image, index) => (
          <img
            key={index}
            src={image}
            alt={`Sketch ${index + 1}`}
            className="shadow-lg mx-auto"
          />
        ))}
      </div>

      {/* Carousel Section */}
      <div className="flex justify-center items-center mt-10">
        <div className="w-full md:w-1/2">
          <Carousel
            autoPlay
            infiniteLoop
            showThumbs={false}
            showStatus={false}
            interval={3000}
            showArrows
          >
            {images2.map((image, index) => (
              <div key={index} className="flex justify-center">
                <img
                  src={image}
                  alt={`Design Slide ${index + 1}`}
                  className="rounded-lg mx-auto"
                />
              </div>
            ))}
          </Carousel>
        </div>
        <img src="/bodyface"/>
      </div>
    </>
  );
}

export default Sketches;
